azureLogAnalytics.query:
performanceCounters
| where $__timeFilter(timestamp)
| where (name == "Available Bytes" and category == "Memory")
| extend value_gb = round(value / 1073741824, 2)
| summarize p95_value = percentile(value_gb, 95), max_value=max(value_gb) by bin(timestamp, $__interval)
| project timestamp, p95_value//,max_value
